('Cloud Operations & Setup','cloud-operations-and-setup','Cloud setup, migration and operational support.',1),('Laptop Repair & Service','laptop-repair-and-service','Professional laptop diagnostics and service.',2),('Desktop Repair & Service','desktop-repair-and-service','Desktop support, upgrades and repair.',3),('iMac Repair & Service','imac-repair-and-service','iMac diagnostics and service.',4),('MacBook Repair & Service','macbook-repair-and-service','MacBook diagnostics and service.',5),('Customized Website Design','customized-website-design','Custom responsive websites for your business.',6),('Custom Application Development','custom-application-development','Purpose-built business applications.',7),('Hosting Solutions','hosting-solutions','Managed hosting solutions.',8),('Email Solutions','email-solutions','Business email setup and support.',9),('Mobile Repair & Service','mobile-repair-and-service','Mobile device repair and support.',10),('Electrical Services','electrical-services','Business electrical services.',11),('CCTV Installation & Repair','cctv-installation-and-repair','CCTV installation, maintenance and repair.',12),('Interior Design Services','interior-design-services','Functional commercial interior solutions.',13) on conflict(slug) do nothing;
